{
  "anomaly_detected": true,
  "confidence": 0.95,
  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["C32"],
      "pins": ["C32.1", "C32.2"],
      "nets": ["+3V3", "GND"],
      "observed": "C32 is populated as a 100 pF capacitor in the schematic value and SPICE deck, but its footprint, library part, datasheet and manufacturer part number all correspond to a 100 nF X7R 0603 capacitor (GRM188R72A104KA35D).",
      "expected": "C32 is a +3V3-to-GND decoupling capacitor and should be 100 nF to match its assigned part and provide adequate rail decoupling.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"C32\") (value \"100p\") (footprint \"Coert-Vonk:CAP X7R 100nF ±10 50V 0603 Murata\") ... (field (name \"PN\") \"GRM188R72A104KA35D\") ... (description \"0.1 µF ±10% 100V Ceramic Capacitor X7R 0603 (1608 Metric)\")"
        },
        {
          "source": "spice",
          "quote": "C32 0 +3V3 100p"
        }
      ],
      "impact": "If the value field is used for assembly, a 100 pF capacitor will be placed instead of 100 nF, reducing decoupling on the +3V3 rail. If the manufacturer part number is used, the board will still receive a 100 nF part, but the design files remain internally inconsistent and simulation does not match the intended BOM.",
      "confidence": 0.95
    }
  ],
  "summary": "The design files are largely consistent, but C32 has a clear value mismatch: the schematic/SPICE value is 100 pF while the assigned part, footprint, description and MPN are for 100 nF. This is a reportable wrong-value anomaly."
}

